import sys; sys.path.insert(0,'/tmp/claude-0/rip'); from est import *
C='LAV-SPEC-B'
E(C,'M1-N1','Le scale portatili',[ES("Esempio guidato · Posizionare una scala portatile","Le regole pratiche prima di salire.",[
 ["Scelta","Scala marcata secondo la UNI EN 131, adatta all’altezza e integra (pioli, piedini antiscivolo).","Scala adatta e integra"],
 ["Inclinazione","La distanza alla base è circa un quarto dell’altezza di appoggio.","Appoggio a 4 m → base a circa 1 m dalla parete"],
 ["Sbarco","Se serve per accedere a un piano, la scala sporge almeno 1 m oltre il piano di sbarco.","Almeno 1 m oltre il piano"],
 ["Salita","Si sale e si scende con il viso verso la scala, mantenendo tre punti di appoggio.","Tre punti di appoggio"],
 ["Lavoro","Niente carichi pesanti in mano e niente sporgersi lateralmente: si sposta la scala.","Il baricentro resta tra i montanti"]],
 "Prima di salire su una scala portatile verifica che sia marcata secondo la norma UNI EN centotrentuno e integra. Posizionala con un’inclinazione corretta: la distanza della base dalla parete è circa un quarto dell’altezza di appoggio, per esempio un metro per quattro metri. Se la usi per raggiungere un piano, deve sporgere almeno un metro oltre il piano di sbarco. Sali e scendi con il viso verso la scala, mantenendo sempre tre punti di appoggio. E non sporgerti: se il punto di lavoro è lontano, scendi e sposta la scala.","Art. 113 D.lgs. 81/2008 · UNI EN 131")])
E(C,'M1-N2','Modalità di impiego dell’estintore portatile',[CL("Quale classe di fuoco?","Seleziona un materiale che brucia, poi la classe di fuoco.",["Classe A · solidi","Classe B · liquidi","Classe C · gas","Classe F · oli da cucina"],[
 ["Carta e cartone",0,"I solidi che formano brace sono classe A."],["Vernici e solventi",1,"I liquidi infiammabili sono classe B."],["Metano",2,"I gas sono classe C."],["Olio della friggitrice",3,"Oli e grassi da cucina sono classe F."],["Legno dei pallet",0,"Il legno è classe A."],["Alcol etilico",1,"È un liquido infiammabile: classe B."]],
 "Sei materiali che possono bruciare. Assegna a ciascuno la classe di fuoco: la classe dice quale estintore usare.","UNI EN 2 · D.M. 1° settembre 2021")])
E(C,'M1-N3','Esercitazione 2 · Caso di studio',[
 SC("La prolunga sotto la scrivania","In ufficio un collega ha collegato stampante, stufetta elettrica e macchina del caffè a una presa multipla, a sua volta inserita in una prolunga avvolta sotto la scrivania. La presa è calda.",[
  ("Che cosa fai per primo?",[["Niente: funziona tutto",False,"Il calore è un segnale di sovraccarico: c’è rischio di incendio."],["Scolleghi gli apparecchi a maggior assorbimento, come la stufetta, e segnali la situazione al preposto",True,"Corretto: riduci subito il carico e segnali il problema."],["Aggiungi un’altra presa multipla per distribuire il carico",False,"Le prese multiple in cascata aumentano il rischio."]]),
  ("La prolunga è avvolta sul rullo. Perché è un problema?",[["Perché si inciampa",False,"Anche, ma il rischio principale è un altro."],["Perché il cavo avvolto si scalda e può danneggiare l’isolamento",True,"Corretto: una prolunga a rullo va svolta completamente quando alimenta carichi elevati."],["Non è un problema",False,"Il cavo avvolto dissipa male il calore."]]),
  ("Il collega vuole aprire la presa per controllare i contatti. È corretto?",[["Sì, con un cacciavite isolato",False,"Gli interventi sugli impianti elettrici sono riservati a personale qualificato."],["No: si segnala il guasto e interviene personale esperto o un’impresa abilitata",True,"Corretto: il lavoratore non interviene su parti elettriche."],["Sì, se stacca prima la corrente",False,"Resta un intervento riservato a personale qualificato."]])],
  "Prese multiple in cascata, prolunghe avvolte e interventi fai-da-te sono tra le cause più frequenti di incendi negli uffici.","Una situazione comune in ufficio. Decidi come intervenire.","Artt. 80-82 D.lgs. 81/2008 · CEI 11-27"),
 AP("Il tuo posto di lavoro","Osserva il tuo ambiente di lavoro.",["Vie di esodo libere","Estintori accessibili e segnalati","Prese e cavi in buono stato","Scale portatili integre","Scaffalature ancorate e con portata indicata","Segnaletica di sicurezza visibile","Pavimenti senza ostacoli"],"Una situazione da migliorare e a chi la segnaleresti","Es.: scatole davanti all’uscita di emergenza del magazzino: lo segnalo al preposto",
  "Guarda il tuo ambiente di lavoro con gli occhi del corso. Spunta ciò che è in ordine e descrivi una situazione da migliorare, indicando a chi la segnaleresti.",3)])
E(C,'M2-N1','Esercitazione 4 · Rischio e misura',[
 CL("Quale fattore di rischio?","Seleziona una situazione, poi il fattore di rischio.",["Videoterminale","Movimentazione manuale dei carichi","Rumore","Microclima"],[
  ["Riflessi della finestra sullo schermo",0,"Riguarda l’ergonomia della postazione al videoterminale."],["Sollevare scatole di risme da terra più volte al giorno",1,"È movimentazione manuale dei carichi."],["Stampante di produzione accanto alla postazione, molto rumorosa",2,"È esposizione al rumore."],["Ufficio a 29 °C d’estate senza ricambio d’aria",3,"È un problema di microclima."],
  ["Sedia senza regolazione dell’altezza",0,"Riguarda la postazione al videoterminale."],["Spingere un carrello pesante su una rampa",1,"Spinta e traino rientrano nella movimentazione manuale dei carichi."],["Correnti d’aria fredda dal condizionatore sulla schiena",3,"È un fattore di discomfort microclimatico."],["Compressore senza cappottatura nel magazzino",2,"È una sorgente di rumore."]],
  "Otto situazioni. Riconosci il fattore di rischio di ciascuna.","Titoli VI, VII e VIII D.lgs. 81/2008"),
 SC("La postazione al videoterminale","Una nuova impiegata lavora al computer circa sette ore al giorno. Lamenta stanchezza agli occhi e dolore al collo.",[
  ("Che cosa controlli per primo nella postazione?",[["Schermo a 50–70 cm, bordo superiore all’altezza degli occhi o poco sotto, senza riflessi",True,"Corretto: distanza, altezza e riflessi dello schermo sono le prime cause di affaticamento visivo e del collo."],["Il colore della scrivania",False,"Non incide in modo rilevante."],["La velocità del computer",False,"Non riguarda l’ergonomia."]]),
  ("Come organizzi le pause?",[["Una pausa di 15 minuti ogni 120 minuti di applicazione continuativa, in assenza di diversa disciplina della contrattazione",True,"Corretto: è la regola dell’art. 175."],["Nessuna pausa se il lavoro è urgente",False,"Le pause o i cambi di attività sono un diritto."],["Una sola pausa a metà giornata",False,"Non è sufficiente per chi lavora sette ore al videoterminale."]]),
  ("È prevista la sorveglianza sanitaria?",[["Sì: è videoterminalista perché usa il videoterminale per almeno 20 ore settimanali",True,"Corretto: la sorveglianza sanitaria comprende anche la valutazione della vista."],["No, solo per chi ha più di 50 anni",False,"Dipende dall’uso del videoterminale, non dall’età."],["Solo se lo chiede la lavoratrice",False,"È obbligatoria per i videoterminalisti."]])],
  "Postazione regolata, pause e sorveglianza sanitaria sono le tre misure di base per chi lavora al videoterminale.","Una nuova impiegata al videoterminale lamenta disturbi. Intervieni nell’ordine giusto.","Artt. 173-176 e Allegato XXXIV D.lgs. 81/2008")])
E(C,'M3-N1','Caso di studio · La lavoratrice e il magazzino',[
 CL("Contenuto o contesto del lavoro?","Seleziona un fattore di stress lavoro-correlato, poi la colonna.",["Contenuto del lavoro","Contesto del lavoro"],[
  ["Carico e ritmo di lavoro",0,"Riguarda il contenuto del lavoro."],["Orario e turni",0,"Rientra nel contenuto del lavoro."],["Ambiente e attrezzature",0,"Rientra nel contenuto del lavoro."],
  ["Autonomia decisionale e controllo",1,"Riguarda il contesto organizzativo."],["Ruolo nell’organizzazione",1,"Riguarda il contesto."],["Sviluppo di carriera",1,"Riguarda il contesto."]],
  "Sei fattori di stress lavoro-correlato. Distingui quelli legati al contenuto del lavoro da quelli legati al contesto organizzativo.","Accordo europeo 8 ottobre 2004 · Metodologia INAIL"),
 ES("Esempio guidato · La consegna dei DPI","Dalla scelta all’uso corretto.",[
  ["Scelta","Il datore di lavoro sceglie i DPI in base alla valutazione dei rischi.","DPI adeguati ai rischi"],["Consegna","Il lavoratore riceve il DPI personale, con la nota informativa del fabbricante.","Consegna documentata"],
  ["Formazione","Per i DPI di III categoria e per i protettori dell’udito è obbligatorio l’addestramento.","Addestramento dove previsto"],["Uso","Il lavoratore usa il DPI conformemente a formazione e addestramento, ne ha cura e non lo modifica.","Art. 78"],
  ["Segnalazione","Difetti o inconvenienti si segnalano subito al datore di lavoro, al dirigente o al preposto.","Segnalare, non riparare"]],
  "Vediamo il percorso di un dispositivo di protezione individuale. Il datore di lavoro lo sceglie in base alla valutazione dei rischi e lo consegna con la nota informativa del fabbricante. Per i dispositivi di terza categoria e per i protettori dell’udito è obbligatorio anche l’addestramento. Il lavoratore lo usa come gli è stato insegnato, ne ha cura, non lo modifica e segnala subito difetti o inconvenienti.","Artt. 74-79 D.lgs. 81/2008"),
 SC("L’allarme di evacuazione","Suona l’allarme di evacuazione mentre sei in archivio al piano interrato. Senti odore di fumo dalle scale principali.",[
  ("Che cosa fai?",[["Finisci di sistemare i documenti e poi esci",False,"All’allarme si interrompe subito l’attività."],["Interrompi l’attività e segui il percorso di esodo alternativo indicato dalla segnaletica",True,"Corretto: se il percorso principale è invaso dal fumo si usa quello alternativo."],["Prendi l’ascensore per fare prima",False,"In caso di incendio l’ascensore non si usa."]]),
  ("Lungo il corridoio incontri un collega che non conosce il percorso. Che cosa fai?",[["Lo accompagni verso l’uscita",True,"Corretto: aiutare chi è in difficoltà senza esporsi a rischi è un comportamento corretto."],["Torni indietro a cercare l’addetto",False,"Non si torna indietro durante l’esodo."],["Gli dici di aspettare i soccorsi",False,"Deve uscire con te."]]),
  ("Arrivato all’esterno, che cosa fai?",[["Vai a casa",False,"Devi raggiungere il punto di raccolta per essere contato."],["Raggiungi il punto di raccolta e ti fai riconoscere dall’addetto",True,"Corretto: il punto di raccolta permette di sapere se manca qualcuno."],["Rientri a prendere la borsa",False,"Non si rientra fino al cessato allarme."]])],
  "Interrompere, seguire il percorso sicuro, aiutare chi è in difficoltà, raggiungere il punto di raccolta: è il comportamento previsto dal piano di emergenza.","Suona l’allarme mentre sei al piano interrato. Decidi come comportarti.","Art. 43 D.lgs. 81/2008 · D.M. 2 settembre 2021"),
 AP("Le emergenze nel tuo luogo di lavoro","Verifica che cosa sai del piano di emergenza.",["Conosco il segnale di allarme","Conosco il percorso di esodo dal mio posto","So dov’è il punto di raccolta","Conosco gli addetti alle emergenze","So dove sono estintori e cassetta di pronto soccorso","Ho partecipato a una prova di evacuazione"],"Che cosa ti manca da conoscere e a chi lo chiederai","Es.: non so dov’è il punto di raccolta: lo chiederò al preposto",
  "Verifica quanto conosci del piano di emergenza del tuo luogo di lavoro e scrivi che cosa ti manca e a chi lo chiederai.",3)])
# ── REATI ──
R='REATI'
E(R,'M1-N1','Esercitazione · Illeciti e procedimenti',[CL("Delitto o contravvenzione?","Seleziona una condotta, poi la categoria.",["Delitto","Contravvenzione"],[
 ["Inquinamento ambientale (art. 452-bis c.p.)",0,"È un delitto introdotto dalla L. 68/2015."],["Superamento dei valori limite di emissione in atmosfera (art. 279 D.lgs. 152/2006)",1,"È una contravvenzione."],
 ["Omessa bonifica (art. 452-terdecies c.p.)",0,"È un delitto."],["Impedimento del controllo (art. 452-septies c.p.)",0,"È un delitto."],
 ["Scarico di acque reflue industriali oltre i limiti tabellari (art. 137 D.lgs. 152/2006)",1,"È una contravvenzione."],["Disastro ambientale (art. 452-quater c.p.)",0,"È un delitto."]],
 "Sei condotte. Distingui i delitti dalle contravvenzioni: la differenza cambia pene, prescrizione e procedure.","Codice penale, Titolo VI-bis · D.lgs. 152/2006")])
E(R,'M1-N2','Esempio applicativo: quando c’è «inquinamento ambientale»',[
 SC("La perdita dal serbatoio interrato","Durante la dismissione di un serbatoio interrato di gasolio, lo scavo mostra terreno impregnato e odore di idrocarburi. Il serbatoio non era mai stato sottoposto a prove di tenuta.",[
  ("Che cosa fai per primo?",[["Riempi lo scavo e completi la dismissione",False,"Nasconderebbe una possibile contaminazione storica."],["Sospendi lo scavo e attui le misure di prevenzione, rimuovendo la sorgente e impedendo la diffusione",True,"Corretto: la contaminazione rilevata, anche storica, obbliga alle misure di prevenzione."],["Aspetti l’esito di analisi tra un mese prima di decidere",False,"Le misure di prevenzione non attendono le analisi."]]),
  ("La contaminazione potrebbe essere vecchia di anni. Va comunicata?",[["No, se il fatto risale a prima della tua gestione",False,"L’art. 242 si applica anche all’individuazione di contaminazioni storiche che possano comportare rischi di aggravamento."],["Sì: si comunica entro 24 ore, come per un nuovo evento",True,"Corretto: la procedura vale anche per le contaminazioni storiche."],["Solo se lo chiede l’ARPA",False,"La comunicazione è un obbligo di chi individua la contaminazione."]]),
  ("Le analisi superano le concentrazioni soglia di contaminazione. Che cosa succede?",[["Piano di caratterizzazione, poi analisi di rischio",True,"Corretto: è la sequenza dell’art. 242."],["Basta smaltire il terreno scavato",False,"Serve verificare l’estensione della contaminazione."],["Si chiude con una sanzione amministrativa",False,"Il procedimento di bonifica prosegue."]])],
  "Anche una contaminazione storica scoperta durante lavori obbliga a prevenire, comunicare e caratterizzare: ometterlo espone ai reati di omessa bonifica e di impedimento del controllo.","Durante la dismissione di un serbatoio emerge una contaminazione. Decidi come procedere.","D.lgs. 152/2006, art. 242, comma 1"),
 ES("Esempio guidato · Dall’evento potenzialmente contaminante alla bonifica","Le tappe dell’art. 242.",[
  ["Entro 24 ore","Misure di prevenzione e comunicazione dell’evento.","Prevenzione + comunicazione"],["Indagine preliminare","Verifica dei parametri rispetto alle concentrazioni soglia di contaminazione (CSC).","Confronto con le CSC"],
  ["CSC non superate","Si ripristina la zona e si autocertifica: il procedimento si chiude, salvo verifiche.","Autocertificazione"],["CSC superate","Piano di caratterizzazione entro 30 giorni.","Caratterizzazione del sito"],
  ["Analisi di rischio","Si determinano le concentrazioni soglia di rischio (CSR): se superate, si progetta la bonifica.","Bonifica o messa in sicurezza"]],
  "Ripercorriamo le tappe dell’articolo duecentoquarantadue. Entro ventiquattro ore si attuano le misure di prevenzione e si comunica l’evento. Segue un’indagine preliminare: se le concentrazioni soglia di contaminazione non sono superate, si ripristina la zona e si autocertifica. Se sono superate, entro trenta giorni si presenta il piano di caratterizzazione; poi l’analisi di rischio individua le concentrazioni soglia di rischio, oltre le quali serve la bonifica o la messa in sicurezza.","D.lgs. 152/2006, art. 242")])
E(R,'M1-N3','Le fasi della procedura estintiva',[
 ES("Esempio guidato · Quanto si paga con la procedura estintiva","Il calcolo per una contravvenzione ambientale (art. 318-quater).",[
  ["La contravvenzione","Superamento dei valori limite di emissione: arresto fino a un anno o ammenda fino a 10.000 €.","Art. 279, comma 2, D.lgs. 152/2006"],
  ["La prescrizione","L’organo di vigilanza impartisce una prescrizione tecnica con un termine per l’adeguamento.","Adeguamento entro il termine"],
  ["La verifica","Accertato l’adempimento, il contravventore è ammesso al pagamento.","Verifica dell’adempimento"],
  ["L’importo","Un quarto del massimo dell’ammenda prevista.","10.000 € ÷ 4 = 2.500 €"],
  ["L’estinzione","Pagamento entro 30 giorni: la contravvenzione si estingue.","Pagamento entro 30 giorni → estinzione"]],
  "Un esempio di procedura estintiva. Il superamento dei valori limite di emissione è punito con l’arresto fino a un anno o con l’ammenda fino a diecimila euro. L’organo di vigilanza impartisce una prescrizione con un termine. Se l’adeguamento è accertato, il contravventore è ammesso a pagare un quarto del massimo dell’ammenda, cioè duemilacinquecento euro, entro trenta giorni: la contravvenzione si estingue.","D.lgs. 152/2006, artt. 318-bis e seguenti"),
 SC("La prescrizione dell’organo di vigilanza","Dopo un sopralluogo ricevi una prescrizione: adeguare il sistema di abbattimento del camino E1 entro 90 giorni. Il fornitore del nuovo filtro annuncia una consegna in 120 giorni.",[
  ("Che cosa fai?",[["Aspetti il filtro e adegui dopo la scadenza",False,"Il mancato adempimento nel termine impedisce l’estinzione."],["Chiedi una proroga motivata prima della scadenza, documentando i tempi di consegna",True,"Corretto: la proroga si chiede prima della scadenza, con motivazioni documentate."],["Ignori la prescrizione: il procedimento si chiuderà da solo",False,"Senza adempimento il procedimento penale prosegue."]]),
  ("Nel frattempo, come gestisci le emissioni?",[["Adotti misure provvisorie per rispettare i limiti, anche riducendo la produzione",True,"Corretto: la conformità va garantita anche durante l’adeguamento."],["Nessuna misura fino al nuovo filtro",False,"Il superamento continuerebbe."],["Spegni il sistema di abbattimento esistente",False,"Peggiora le emissioni."]]),
  ("Completato l’adeguamento, che cosa fai?",[["Lo comunichi all’organo di vigilanza con la documentazione e attendi la verifica",True,"Corretto: la verifica dell’adempimento apre la fase del pagamento."],["Nulla: l’organo lo scoprirà al prossimo controllo",False,"L’adempimento va comunicato e verificato."],["Paghi subito senza attendere la verifica",False,"Il pagamento avviene dopo l’ammissione."]])],
  "Rispettare il termine o chiedere per tempo la proroga, garantire la conformità nel frattempo, comunicare l’adempimento: è così che la procedura estintiva funziona a favore dell’impresa.","Hai ricevuto una prescrizione con un termine stretto. Gestiscila correttamente.","D.lgs. 152/2006, Parte VI-bis")])
E(R,'M1-N4','Sanzioni all’ente: quote, interdittive, confisca',[
 ES("Esempio guidato · La sanzione pecuniaria all’ente","Il sistema per quote del D.lgs. 231/2001.",[
  ["Il reato presupposto","Inquinamento ambientale commesso nell’interesse dell’ente.","Art. 25-undecies: da 250 a 600 quote"],
  ["Il numero di quote","Il giudice lo fissa in base a gravità del fatto, grado di responsabilità e attività svolte per attenuare le conseguenze.","Esempio: 300 quote"],
  ["Il valore della quota","Il giudice lo fissa tra 258 e 1.549 € in base alle condizioni economiche dell’ente.","Esempio: 800 € per quota"],
  ["La sanzione","Numero di quote per valore della quota.","300 × 800 = 240.000 €"],
  ["Le interdittive","Per alcuni reati si aggiungono sanzioni interdittive, come il divieto di contrattare con la pubblica amministrazione.","Oltre alla sanzione pecuniaria"]],
  "La sanzione pecuniaria all’ente si calcola per quote. Per l’inquinamento ambientale l’articolo venticinque undecies prevede da duecentocinquanta a seicento quote. Il giudice fissa il numero di quote in base alla gravità del fatto e alla responsabilità dell’ente, e il valore di ciascuna quota, tra duecentocinquantotto e millecinquecentoquarantanove euro, in base alle condizioni economiche. Con trecento quote da ottocento euro la sanzione è di duecentoquarantamila euro, a cui possono aggiungersi sanzioni interdittive.","D.lgs. 231/2001, artt. 10, 11 e 25-undecies"),
 CL("Chi risponde?","Seleziona una situazione, poi chi ne risponde.",["La persona fisica che ha commesso il reato","Anche l’ente, ai sensi del D.lgs. 231/2001"],[
  ["Il responsabile di produzione autorizza uno scarico non autorizzato per risparmiare sui costi di trattamento",1,"Il reato è commesso nell’interesse dell’ente: risponde anche l’ente, se il reato è tra quelli dell’art. 25-undecies."],
  ["Un dipendente abbandona di sua iniziativa rifiuti propri in un campo, fuori dall’orario di lavoro",0,"Non c’è interesse o vantaggio dell’ente: risponde la persona."],
  ["L’amministratore sceglie un trasportatore di rifiuti non iscritto all’Albo perché costa meno",1,"Il risparmio è un vantaggio per l’ente."],
  ["Un tecnico esterno falsifica un rapporto di prova all’insaputa dell’impresa e senza alcun vantaggio per essa",0,"Senza interesse o vantaggio dell’ente risponde chi ha commesso il fatto."]],
  "Quattro situazioni. Valuta se risponde solo la persona fisica o anche l’ente.","D.lgs. 231/2001, artt. 5 e 25-undecies")])
E(R,'M1-N5','Le segnalazioni di illeciti: il D.lgs. 24/2023',[
 SC("La segnalazione del magazziniere","Un magazziniere nota che fusti di solvente esausto vengono caricati su un furgone senza formulario. Teme ritorsioni.",[
  ("Che cosa può fare?",[["Nulla: non è affar suo",False,"Il D.lgs. 24/2023 tutela chi segnala violazioni nel contesto lavorativo."],["Usare il canale di segnalazione interno dell’impresa",True,"Corretto: il canale interno garantisce la riservatezza dell’identità del segnalante."],["Pubblicare subito un video sui social",False,"La divulgazione pubblica è tutelata solo in condizioni specifiche, dopo i canali interni ed esterni o in caso di pericolo imminente."]]),
  ("Chi gestisce la segnalazione?",[["Il responsabile del magazzino coinvolto",False,"Chi gestisce le segnalazioni deve essere autonomo e formato, non coinvolto nei fatti."],["Il gestore del canale individuato dall’impresa, che dà riscontro nei termini previsti",True,"Corretto: avviso di ricevimento entro 7 giorni e riscontro entro 3 mesi."],["Nessuno: le segnalazioni anonime si archiviano",False,"Le segnalazioni vanno gestite secondo la procedura."]]),
  ("Dopo la segnalazione il magazziniere viene trasferito a un turno sgradito. Che cosa prevede la legge?",[["È una ritorsione vietata, che può essere comunicata all’ANAC",True,"Corretto: il D.lgs. 24/2023 vieta le ritorsioni e prevede sanzioni."],["È legittimo se deciso dal capo reparto",False,"Le misure ritorsive sono nulle."],["Il segnalante perde la tutela",False,"La tutela resta se la segnalazione è fatta in buona fede."]])],
  "Canale interno, riservatezza, riscontro nei tempi e divieto di ritorsioni: sono le garanzie che rendono utile la segnalazione anche per prevenire reati ambientali.","Un lavoratore vede una gestione irregolare dei rifiuti. Accompagnalo nella segnalazione.","D.lgs. 24/2023"),
 AP("La mappa dei rischi ambientali della tua azienda","Individua le attività sensibili per i reati ambientali.",["Scarichi idrici","Emissioni in atmosfera","Gestione dei rifiuti e scelta dei trasportatori","Stoccaggio di sostanze pericolose","Serbatoi interrati o fuori terra","Impianti con gas fluorurati","Terreni o falde potenzialmente contaminati"],"Le due attività più sensibili e il controllo che proporresti","Es.: scelta dei trasportatori di rifiuti → verifica iscrizione all’Albo prima di ogni contratto",
  "Individua le attività della tua azienda più esposte ai reati ambientali e scrivi per le due più sensibili il controllo che proporresti.",3),
 VF("Ripasso · Responsabilità ambientale",[["La procedura estintiva si applica alle contravvenzioni che non hanno cagionato danno o pericolo concreto e attuale.",True,"Vero: art. 318-bis D.lgs. 152/2006."],["L’evento potenzialmente contaminante va comunicato entro 24 ore.",True,"Vero: art. 242."],["L’ente risponde sempre dei reati commessi dai propri dipendenti.",False,"Falso: serve un reato presupposto commesso nell’interesse o a vantaggio dell’ente."]],"Ripasso: tre affermazioni sulla responsabilità ambientale.","D.lgs. 152/2006 · D.lgs. 231/2001")])

E(R,'M1-N6','Chi risponde in azienda: posizioni di garanzia e delega',[
 SC("La delega al responsabile ambientale","L’amministratore unico di un’impresa manifatturiera vuole delegare la gestione ambientale al responsabile di stabilimento.",[
  ("Come deve essere conferita la delega?",[["A voce, durante una riunione",False,"La delega deve risultare da atto scritto, con data certa, e va accettata."],["Con atto scritto e data certa, accettato dal delegato",True,"Corretto: la forma scritta e l’accettazione rendono la delega opponibile."],["Con una semplice e-mail non firmata",False,"Non garantisce data certa né accettazione."]]),
  ("Il responsabile di stabilimento non può spendere più di 2.000 € senza autorizzazione. È un problema?",[["No, conta solo il titolo",False,"Senza autonomia di spesa adeguata il delegato non può adempiere."],["Sì: il delegato deve avere poteri di organizzazione, gestione, controllo e autonomia di spesa adeguati",True,"Corretto: senza poteri effettivi la delega non trasferisce la responsabilità."],["Dipende dal fatturato dell’impresa",False,"Conta l’adeguatezza dei poteri rispetto ai compiti."]]),
  ("Conferita la delega, l’amministratore non ha più obblighi?",[["Non ha più alcun obbligo",False,"Resta l’obbligo di vigilanza sul corretto espletamento delle funzioni delegate."],["Resta l’obbligo di vigilare sull’operato del delegato",True,"Corretto: la delega non elimina il dovere di vigilanza del delegante."],["Deve ripetere personalmente tutti i controlli",False,"Deve vigilare, non sostituirsi al delegato."]])],
  "Forma scritta, professionalità del delegato, poteri e autonomia di spesa adeguati, vigilanza del delegante: sono i requisiti che la giurisprudenza richiede anche in materia ambientale, in analogia con l’art. 16 del D.lgs. 81/2008.","Una delega di funzioni in materia ambientale. Valuta se è efficace.","Art. 16 D.lgs. 81/2008 · giurisprudenza di legittimità")])
E(R,'M1-N7','Ravvedimento operoso, confisca e ripristino dello stato dei luoghi',[
 ES("Esempio guidato · Il ravvedimento operoso","Come la condotta dopo il fatto riduce la pena (art. 452-decies c.p.).",[
  ["Il fatto","Un’impresa è imputata di inquinamento ambientale per uno scarico che ha compromesso un corso d’acqua.","Art. 452-bis c.p."],
  ["La scelta","Prima dell’apertura del dibattimento di primo grado provvede concretamente alla messa in sicurezza e alla bonifica.","Azione prima del dibattimento"],
  ["L’effetto","Le pene sono diminuite dalla metà a due terzi.","Riduzione da 1/2 a 2/3"],
  ["La collaborazione","Chi aiuta concretamente l’autorità nella ricostruzione del fatto ottiene una diminuzione da un terzo alla metà.","Riduzione da 1/3 a 1/2"],
  ["La sospensione","Il procedimento può essere sospeso per il tempo necessario alle attività, entro i limiti di legge.","Tempo per bonificare"]],
  "Il ravvedimento operoso premia chi rimedia. Se prima dell’apertura del dibattimento di primo grado l’impresa provvede concretamente alla messa in sicurezza e alla bonifica, le pene sono diminuite dalla metà a due terzi. Chi aiuta concretamente l’autorità a ricostruire il fatto ottiene una diminuzione da un terzo alla metà. Il procedimento può essere sospeso per il tempo necessario a eseguire le attività.","Art. 452-decies c.p.")])
E(R,'M1-N8','Obblighi dell’operatore: prevenzione e riparazione',[
 CL("Quale tipo di riparazione?","Seleziona un intervento, poi il tipo di riparazione del danno ambientale.",["Primaria","Complementare","Compensativa"],[
  ["Rimuovere i sedimenti contaminati e riportare il fiume alle condizioni originarie",0,"La riparazione primaria riporta le risorse danneggiate alle condizioni originarie."],
  ["Ricostituire una zona umida in un tratto vicino, perché quella danneggiata non è recuperabile del tutto",1,"La complementare compensa il mancato ripristino completo."],
  ["Creare un habitat aggiuntivo per compensare le perdite subite in attesa del ripristino",2,"La compensativa copre le perdite temporanee."],
  ["Ripiantare la vegetazione ripariale distrutta nello stesso sito",0,"È ripristino delle condizioni originarie: primaria."],
  ["Migliorare un’area protetta vicina per la perdita temporanea di fruizione",2,"Compensa le perdite provvisorie: compensativa."],
  ["Creare un nuovo sito di riproduzione per una specie che non può tornare nel sito originario",1,"Sopperisce al ripristino incompleto: complementare."]],
  "Sei interventi dopo un danno ambientale. Riconosci il tipo di riparazione previsto dalla Parte VI.","D.lgs. 152/2006, Allegato 3 alla Parte VI"),
 AP("Le deleghe e i controlli nella tua azienda","Verifica l’organizzazione della responsabilità ambientale.",["Esiste un responsabile ambientale con compiti scritti","Esiste una delega di funzioni formalizzata","Il delegato ha un budget adeguato","Il vertice riceve report periodici","Esiste una procedura per gli eventi potenzialmente contaminanti","È adottato un modello organizzativo ai sensi del D.lgs. 231/2001"],"Il punto più debole e l’azione che proporresti","Es.: il delegato non ha budget → proporre un budget annuo per gli adempimenti ambientali",
  "Verifica come è organizzata la responsabilità ambientale nella tua azienda e indica il punto più debole e l’azione che proporresti.",3)])
